	}
	if got := l.RetryAfter(1); got != 500*time.Millisecond {
		t.Fatalf("RetryAfter(1) = %v, want %v", got, 500*time.Millisecond)
	}
	if got := l.RetryAfter(0); got != 0 {
		t.Fatalf("RetryAfter(0) = %v, want 0", got)
	}
	c.Advance(500 * time.Millisecond)
	if got := l.RetryAfter(1); got != 0 {
		t.Fatalf("RetryAfter(1) after refill = %v, want 0", got)
	}
}

func TestConcurrentAccess(t *testing.T) {
	c := newFakeClock()
	l, err := New(1000, 100, c)
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	var wg sync.WaitGroup
	allowed := make([]bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			allowed[i] = l.Allow()
		}(i)
	}
	wg.Wait()
	count := 0
	for _, ok := range allowed {
		if ok {
			count++
		}
	}
	if count != 100 {
		t.Fatalf("allowed %d requests, want exactly 100 (burst)", count)
	}
}
